DROP POLICY "Anyone can log a click" ON public.affiliate_clicks;
ALTER POLICY "Anyone can log analytics" ON public.analytics_events WITH CHECK (kind IN ('page_view','recipe_view','product_view','blog_view','cta_click','internal_link_click','homepage_click','checkout_start','pinterest_click','download','free_cookbook_view','free_cookbook_download','free_cookbook_signup','upsell_click') AND (ref_slug IS NULL OR length(ref_slug) <= 240) AND session_id IS NOT NULL AND length(session_id) BETWEEN 1 AND 120 AND jsonb_typeof(metadata) = 'object' AND octet_length(metadata::text) <= 8192);
ALTER POLICY "Anyone can read pricing" ON public.pricing_settings USING (id = true);
ALTER POLICY "site_settings public read" ON public.site_settings USING (key IN ('nav','footer','trust_badges','why_choose'));
ALTER POLICY "homepage_sections public read" ON public.homepage_sections USING (enabled = true);
ALTER POLICY "content_categories public read" ON public.content_categories USING ((content_type = 'recipe' AND EXISTS (SELECT 1 FROM public.recipes r WHERE r.id = content_id AND r.status = 'published')) OR (content_type = 'blog' AND EXISTS (SELECT 1 FROM public.blog_posts b WHERE b.id = content_id AND b.status = 'published')) OR (content_type = 'product' AND EXISTS (SELECT 1 FROM public.products p WHERE p.id = content_id AND p.status = 'published')));
ALTER POLICY "content_collections public read" ON public.content_collections USING ((content_type = 'recipe' AND EXISTS (SELECT 1 FROM public.recipes r WHERE r.id = content_id AND r.status = 'published')) OR (content_type = 'blog' AND EXISTS (SELECT 1 FROM public.blog_posts b WHERE b.id = content_id AND b.status = 'published')) OR (content_type = 'product' AND EXISTS (SELECT 1 FROM public.products p WHERE p.id = content_id AND p.status = 'published')));
ALTER POLICY "content_relations public read" ON public.content_relations USING (((from_type = 'recipe' AND EXISTS (SELECT 1 FROM public.recipes r WHERE r.id = from_id AND r.status = 'published')) OR (from_type = 'blog' AND EXISTS (SELECT 1 FROM public.blog_posts b WHERE b.id = from_id AND b.status = 'published')) OR (from_type = 'product' AND EXISTS (SELECT 1 FROM public.products p WHERE p.id = from_id AND p.status = 'published'))) AND ((to_type = 'recipe' AND EXISTS (SELECT 1 FROM public.recipes r WHERE r.id = to_id AND r.status = 'published')) OR (to_type = 'blog' AND EXISTS (SELECT 1 FROM public.blog_posts b WHERE b.id = to_id AND b.status = 'published')) OR (to_type = 'product' AND EXISTS (SELECT 1 FROM public.products p WHERE p.id = to_id AND p.status = 'published'))));
ALTER POLICY "categories public read" ON public.categories USING (EXISTS (SELECT 1 FROM public.content_categories cc WHERE cc.category_id = categories.id));
ALTER POLICY "collections public read" ON public.collections USING (EXISTS (SELECT 1 FROM public.content_collections cc WHERE cc.collection_id = collections.id));
ALTER POLICY "Categories are readable by anyone" ON public.product_categories USING (EXISTS (SELECT 1 FROM public.products p WHERE p.category_id = product_categories.id AND p.status = 'published'));
ALTER POLICY "media public read" ON public.media USING (EXISTS (SELECT 1 FROM public.recipes r WHERE r.status = 'published' AND (r.hero_image_id = media.id OR media.id = ANY(r.gallery_ids))) OR EXISTS (SELECT 1 FROM public.blog_posts b WHERE b.status = 'published' AND b.hero_image_id = media.id) OR EXISTS (SELECT 1 FROM public.products p WHERE p.status = 'published' AND p.cover_image_id = media.id) OR EXISTS (SELECT 1 FROM public.categories c WHERE c.image_id = media.id) OR EXISTS (SELECT 1 FROM public.collections c WHERE c.image_id = media.id));
CREATE POLICY "Boss reads all pricing" ON public.pricing_settings FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'boss'));